-- Finance (spec 005): invoices (advance, progress statement, final), payments, reminders, online
-- payment intents and each company's payment provider. Amounts are integers in minor units; VAT,
-- retention and totals are generated by the database, never computed by a client.

create table org_counter (
  org_id text not null references organization(id) on delete cascade,
  name text not null,
  value integer not null default 0,
  primary key (org_id, name)
);

create table invoice (
  id uuid primary key default gen_random_uuid(),
  org_id text not null references organization(id) on delete cascade,
  project_id uuid not null,
  number text not null,
  kind text not null check (kind in ('advance', 'progress', 'final')),
  label text,
  issued_on date not null default current_date,
  due_on date not null,
  currency_code text not null check (currency_code ~ '^[A-Z]{3}$'),
  amount_minor bigint not null check (amount_minor >= 0),
  vat_bps integer not null check (vat_bps between 0 and 10000),
  retention_bps integer not null check (retention_bps between 0 and 10000),
  -- Advance already paid, deducted from this statement.
  deduction_minor bigint not null default 0 check (deduction_minor >= 0),
  vat_minor bigint generated always as ((amount_minor * vat_bps + 5000) / 10000) stored,
  total_minor bigint generated always as (amount_minor + (amount_minor * vat_bps + 5000) / 10000) stored,
  retention_minor bigint generated always as
    (((amount_minor + (amount_minor * vat_bps + 5000) / 10000) * retention_bps + 5000) / 10000) stored,
  net_minor bigint generated always as (
    amount_minor + (amount_minor * vat_bps + 5000) / 10000
    - ((amount_minor + (amount_minor * vat_bps + 5000) / 10000) * retention_bps + 5000) / 10000
    - deduction_minor) stored,
  status text not null default 'issued' check (status in ('draft', 'issued', 'cancelled')),
  created_by text references "user"(id),
  created_at timestamptz not null default now(),
  unique (org_id, number),
  unique (id, org_id),
  foreign key (project_id, org_id) references project (id, org_id) on delete cascade,
  check (due_on >= issued_on),
  check (deduction_minor <= amount_minor + (amount_minor * vat_bps + 5000) / 10000)
);
create index invoice_project_idx on invoice (project_id, issued_on);

create table payment (
  id uuid primary key default gen_random_uuid(),
  org_id text not null references organization(id) on delete cascade,
  project_id uuid not null,
  invoice_id uuid,
  received_on date not null default current_date,
  amount_minor bigint not null check (amount_minor > 0),
  currency_code text not null check (currency_code ~ '^[A-Z]{3}$'),
  method text not null check (method in ('mobile_money', 'transfer', 'cheque', 'cash', 'card', 'other')),
  reference text,
  note text,
  created_by text references "user"(id),
  created_at timestamptz not null default now(),
  foreign key (project_id, org_id) references project (id, org_id) on delete cascade,
  foreign key (invoice_id, org_id) references invoice (id, org_id) on delete set null (invoice_id)
);
create index payment_project_idx on payment (project_id, received_on);
create index payment_invoice_idx on payment (invoice_id);

create table reminder (
  id uuid primary key default gen_random_uuid(),
  org_id text not null references organization(id) on delete cascade,
  invoice_id uuid not null,
  kind text not null check (kind in ('reminder', 'formal_notice')),
  channel text not null check (channel in ('email', 'whatsapp', 'sms', 'phone', 'letter')),
  body text,
  sent_at timestamptz not null default now(),
  created_by text references "user"(id),
  foreign key (invoice_id, org_id) references invoice (id, org_id) on delete cascade
);
create index reminder_invoice_idx on reminder (invoice_id, sent_at desc);

create table payment_intent (
  id uuid primary key default gen_random_uuid(),
  org_id text not null references organization(id) on delete cascade,
  invoice_id uuid not null,
  provider text not null,
  provider_ref text,
  amount_minor bigint not null check (amount_minor > 0),
  currency_code text not null,
  status text not null default 'pending' check (status in ('pending', 'succeeded', 'failed', 'cancelled')),
  checkout_url text,
  payment_id uuid references payment(id),
  created_at timestamptz not null default now(),
  completed_at timestamptz,
  foreign key (invoice_id, org_id) references invoice (id, org_id) on delete cascade
);
create unique index payment_intent_provider_ref_idx on payment_intent (provider, provider_ref)
  where provider_ref is not null;

-- Each company's own payment account: money paid by its clients goes to it, never to Struo.
-- Secrets are encrypted by the application before they reach this table.
create table org_payment_provider (
  org_id text primary key references organization(id) on delete cascade,
  provider text not null,
  secret_enc text,
  webhook_secret_enc text,
  enabled boolean not null default true,
  updated_at timestamptz not null default now()
);

do $$
declare t text;
begin
  foreach t in array array['org_counter', 'invoice', 'payment', 'reminder', 'payment_intent', 'org_payment_provider'] loop
    execute format('alter table %I enable row level security', t);
    execute format(
      'create policy %I on %I using (struo_is_member(org_id)) with check (struo_is_member(org_id))',
      t || '_member', t);
  end loop;
end $$;

-- Next number of a counter (« F-2026-0001 »), under a row lock.
create function struo_next_number(target_org text, counter text) returns integer
  language plpgsql
  as $$
declare result integer;
begin
  insert into org_counter (org_id, name, value) values (target_org, counter, 1)
  on conflict (org_id, name) do update set value = org_counter.value + 1
  returning value into result;
  return result;
end $$;

-- What is paid and what is left on each issued invoice.
create view invoice_balance with (security_invoker = true) as
select i.id as invoice_id,
       i.org_id,
       i.project_id,
       i.number,
       i.kind,
       i.issued_on,
       i.due_on,
       i.currency_code,
       i.total_minor,
       i.retention_minor,
       i.net_minor,
       coalesce(sum(p.amount_minor), 0)::bigint as paid_minor,
       greatest(i.net_minor - coalesce(sum(p.amount_minor), 0), 0)::bigint as balance_minor,
       case when i.net_minor - coalesce(sum(p.amount_minor), 0) > 0 and i.due_on < current_date
            then (current_date - i.due_on) else 0 end as overdue_days
from invoice i
left join payment p on p.invoice_id = i.id
where i.status = 'issued'
group by i.id;
